"""Read-only PCP Local view using the existing dashboard style and session API."""
from .dashboard_ui_base import DASHBOARD_HTML

_STYLE = DASHBOARD_HTML.split('<style>', 1)[1].split('</style>', 1)[0]
LOCAL_DASHBOARD_HTML = '''<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>PCP Local Activity</title><style>''' + _STYLE + '''
.local-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:14px}.local-value{overflow-wrap:anywhere}dl{margin:0}dt{color:var(--muted);font-size:12px;margin-top:10px}dd{margin:2px 0 8px;overflow-wrap:anywhere}button,input{font:inherit;padding:10px;border-radius:8px;border:1px solid var(--border);background:var(--panel);color:var(--text)}#connection{position:sticky;top:0;background:var(--bg);padding:12px 0;z-index:2}.error{color:var(--red)}li{margin:8px 0}.local-job{margin-bottom:18px}h2{overflow-wrap:anywhere}
</style></head><body><main class="wrap"><div class="eyebrow">Personal Coding Platform</div>
<h1 class="title">PCP Local Activity</h1><p class="sub">Read-only observation · service health does not prove developer activity.</p>
<div id="connection" role="status">Connecting…</div>
<form id="login" hidden><label for="token">Dashboard read token</label> <input id="token" type="password" autocomplete="off" required><button>Sign in</button><p id="loginError" class="error"></p></form>
<div id="instance" class="card section"></div><div id="jobs"></div>
</main><script>
const $=s=>document.querySelector(s);const esc=v=>String(v??'Unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const value=v=>v===null||v===undefined?'Unknown':Array.isArray(v)?(v.length?'<ul>'+v.map(x=>'<li>'+value(x)+'</li>').join('')+'</ul>':'None observed'):typeof v==='object'?rows(v):typeof v==='boolean'?(v?'Yes':'No'):esc(v).replaceAll('_',' ');
const rows=obj=>'<dl>'+Object.entries(obj).map(([k,v])=>'<dt>'+esc(k.replaceAll('_',' '))+'</dt><dd>'+value(v)+'</dd>').join('')+'</dl>';
const link=(url,label)=>url?'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>':esc(label)+': Unknown';
let snapshot=null,lastSuccess=null;
function freshness(){if(!lastSuccess)return;const seconds=Math.floor((Date.now()-lastSuccess)/1000);if(seconds>10)$('#connection').textContent='Offline · last successful observation '+seconds+'s ago; retained data may be stale'}
function render(v){const d=new Date(v.generated_at);$('#connection').textContent=v.observation==='available'?'Observed '+d.toLocaleString()+' · refreshed every 3s':'State unavailable · check the scoped database and schema; no job action was taken';$('#instance').innerHTML=rows({instance:v.instance,source:v.source,observation:v.observation,services:v.services,developer_activity:v.developer_activity,readiness:v.readiness,provider_quota:v.quota});
$('#jobs').innerHTML=v.jobs.length?v.jobs.map(j=>'<article class="card local-job"><h2>Job '+esc(j.id)+'</h2><p>'+link(j.issue_url,'Issue #'+(j.issue??'Unknown'))+' · '+esc(j.status)+(j.activity!==j.status?' · '+esc(j.activity):'')+'</p><div class="local-grid"><section><h3>Current state</h3>'+rows({actual_stage:j.stage,admitted:j.admitted_at,started:j.started_at,elapsed_seconds:j.elapsed_seconds,observed_execution_seconds:j.observed_execution_seconds,last_activity:j.last_activity_at,activity_age_seconds:j.activity_age_seconds,model:j.model,blocker:j.blocker,responsible_actor:j.responsible_actor,next_action:j.next_action,assisted_recovery:j.assisted_recovery})+'</section><section><h3>Usage observations</h3>'+rows(j.usage)+rows({last_attempt:j.last_attempt_usage})+'<h3>Ownership</h3>'+rows({receipt:j.receipt,lease:j.lease})+'</section><section><h3>Verification and delivery</h3><p>Local verification is separate from hosted CI.</p>'+rows(j.local_verification)+rows({mandatory_phases:j.phases,hosted_ci:j.hosted_ci,milestones:j.milestones})+'<p>'+link(j.commit_url,'Commit')+' · '+link(j.pr_url,'Draft PR')+'</p></section></div><h3>Timeline · durable recorded events</h3><ol>'+j.timeline.slice().sort((a,b)=>a.seq-b.seq).map(e=>'<li>'+esc(e.timestamp)+' · '+esc(e.phase)+' · '+esc(e.message)+'</li>').join('')+'</ol>'+(j.timeline.length?'':'<p class="small">No recorded public events. Verification and delivery evidence are shown above.</p>')+'</article>').join(''):'<section class="card"><h2>'+esc(v.state==='unavailable'?'Unavailable':'No admitted jobs')+'</h2><p>Waiting for approved work or authentication/readiness. No model is started by this dashboard.</p></section>'}
async function refresh(){try{const r=await fetch('/v1/dashboard/snapshot',{cache:'no-store'});if(r.status===401||r.status===503){$('#login').hidden=false;$('#connection').textContent=r.status===401?'Waiting for dashboard authentication':'Dashboard read authentication unavailable';return}if(!r.ok)throw Error('Unavailable');snapshot=await r.json();lastSuccess=Date.now();$('#login').hidden=true;render(snapshot)}catch(e){$('#connection').textContent='Offline · observation unavailable; retained data may be stale'}}
$('#login').onsubmit=async e=>{e.preventDefault();const token=$('#token').value;$('#token').value='';try{const r=await fetch('/v1/dashboard/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token})});if(!r.ok){$('#loginError').textContent='Sign-in failed';return}$('#loginError').textContent='';await refresh()}catch(e){$('#loginError').textContent='Authentication service unavailable'}};
refresh();setInterval(refresh,3000);setInterval(freshness,1000);
</script></body></html>'''
